import json,time,urllib.parse,gzip,os
class H(BaseHTTPRequestHandler):
 protocol_version='HTTP/1.1'
 def log_message(self,*a):pass
 def do_GET(self):self.handle_req()
 def do_POST(self):self.handle_req()
 def do_PUT(self):self.handle_req()
 def do_PATCH(self):self.handle_req()
 def do_DELETE(self):self.handle_req()
 def do_HEAD(self):self.handle_req()
 def do_OPTIONS(self):self.handle_req()
 def handle_req(self):
  length=int(self.headers.get('Content-Length',0))
  body=self.rfile.read(length) if length else b''
  path=urllib.parse.urlsplit(self.path)
  args=urllib.parse.parse_qs(path.query)
  if path.path.startswith('/delay'):
   time.sleep(float(args.get('s',['.1'])[0]))
  status=200; data=b'hello'; extra={}
  if path.path.startswith('/status/'):
   status=int(path.path.split('/')[2]);data=('status '+str(status)).encode()
  elif path.path=='/echo':
   data=json.dumps({'method':self.command,'path':self.path,'version':self.request_version,'headers':dict(self.headers),'body':body.decode(errors='replace')},separators=(',',':')).encode()
  elif path.path=='/redirect':
   status=int(args.get('s',['302'])[0]);extra['Location']=args.get('to',['/echo'])[0];data=b'redirect body'
  elif path.path=='/loop':
   status=302;extra['Location']='/loop';data=b'loop'
  elif path.path=='/gzip':
   data=gzip.compress(b'hello compressed'*20);extra['Content-Encoding']='gzip'
  elif path.path=='/bytes':data=b'x'*int(args.get('n',['0'])[0])
  elif path.path=='/binary':data=bytes([0,10,255,34,92,13,128])
  elif path.path=='/close':self.connection.close();return
  with open('/tmp/oha_requests.log','a') as f:
