import errno
import os
import sys

VERSION = '1.12.1'

class Failure(Exception):
    def __init__(self, message, code=1):
        self.message = message
        self.code = code
        super().__init__(message)


def os_error(e):
    n = getattr(e, 'errno', None)
    if n is not None and n > 0:
        return f'{os.strerror(n)} (os error {n})'
    return str(e)


def read_file(path, text=False):
    try:
        with open(path, 'rb') as f:
            data = f.read()
        if text:
            try:
                return data.decode('utf-8')
            except UnicodeError:
                raise Failure('stream did not contain valid UTF-8')
        return data
    except OSError as e:
        raise Failure(os_error(e))


def rust_bytes(data):
    out = []
    esc = {0: '\\0', 9: '\\t', 10: '\\n', 13: '\\r', 34: '\\"', 92: '\\\\'}
    for ch in data:
        if ch in esc:
            out.append(esc[ch])
        elif 32 <= ch <= 126:
            out.append(chr(ch))
        else:
            out.append(f'\\x{ch:02x}')
    return 'b"' + ''.join(out) + '"'


def header_repr(value):
    # HeaderValue's debug notation differs from Rust string escaping.
    if isinstance(value, str):
        value = value.encode('utf-8')
    chars = []
    for c in value:
        if c == 34: chars.append('\\"')
        elif c == 92: chars.append('\\\\')
        elif c == 9 or 32 <= c < 127: chars.append(chr(c))
        else: chars.append(f'\\x{c:02x}')
    return '"' + ''.join(chars) + '"'
