        self.url = None
        self.seen = []
        self.program = os.path.basename(sys.argv[0]) or 'executable'

    def usage(self, opts=None):
        mid = '[OPTIONS]' if opts is None else ' '.join(o.display for o in opts)
        return f'Usage: {self.program}' + (' ' + mid if mid else '') + ' <URL>\n'

    def fail(self, text, usage=None):
        if usage is not None:
            text += '\n\n' + self.usage(usage)
        else:
            text += '\n'
        raise Failure(text + TRAILER, 2)

    def invalid(self, opt, val, msg=None, choices=None):
        text = f"error: invalid value '{val}' for '{opt.display}'"
