import ipaddress
import random
import re
import unicodedata
import urllib.parse
from common import Failure, read_file

SPECIAL = {'http': 80, 'https': 443, 'ftp': 21, 'ws': 80, 'wss': 443, 'file': None}


def encode_component(value, extra):
    out = []
    for c in value.encode('utf-8'):
        if c < 33 or c >= 127 or chr(c) in extra:
            out.append('%' + format(c, '02X'))
        else: out.append(chr(c))
    return ''.join(out)


def ipv4_name(host):
    seg = host.split('.')
    if seg[-1] == '': seg.pop()
    if not seg: return None
    def number(s):
        base = 10
        if len(s) >= 2 and s[:2].lower() == '0x': s, base = s[2:], 16
        elif len(s) >= 2 and s[0] == '0': s, base = s[1:], 8
        if not s: return 0
        if not re.fullmatch('[0-9A-Fa-f]+' if base == 16 else '[0-7]+' if base == 8 else '[0-9]+', s):
            raise ValueError()
        return int(s, base)
    last = seg[-1]
    try:
        number(last)
        numeric = True
    except ValueError:
        numeric = last.isascii() and last.isdigit()
    if not numeric: return None
    try:
        parts = [number(s) for s in seg]
        if len(parts) > 4 or any(x > 255 for x in parts[:-1]) or parts[-1] >= 256 ** (5 - len(parts)):
            raise ValueError()
        n = parts[-1]
        for i, part in enumerate(parts[:-1]): n += part << (8 * (3 - i))
        return str(ipaddress.IPv4Address(n))
    except (ValueError, OverflowError): raise Failure('invalid IPv4 address')


def clean_host(host, special):
    if host.startswith('['):
        if not host.endswith(']'): raise Failure('invalid IPv6 address')
        try: return '[' + str(ipaddress.IPv6Address(host[1:-1])) + ']'
        except ValueError: raise Failure('invalid IPv6 address')
    if not special:
        if any(c in '\x00\t\n\r #/:<>?@[\\]^|' for c in host): raise Failure('invalid domain character')
        return encode_component(host, '')
    try:
        h = urllib.parse.unquote_to_bytes(host).decode('utf-8')
        h = unicodedata.normalize('NFKC', h).lower()
        if any(c in '\x00\t\n\r #/:<>?@[\\]^|%' for c in h):
            raise ValueError()
        # IDNA's domain labels are used only where non-ASCII is present;
        # URL hosts otherwise permit, for example, underscores.
        h = '.'.join(label if label.isascii() else 'xn--' + label.encode('punycode').decode('ascii') for label in h.split('.'))
    except (UnicodeError, ValueError): raise Failure('invalid international domain name')
    v4 = ipv4_name(h)
    return v4 if v4 is not None else h


def clean_path(path):
    segs = path.split('/')
    out = []
    for i, s in enumerate(segs):
        dot = re.sub('(?i)%2e', '.', s)
        if dot == '.':
            if i == len(segs) - 1: out.append('')
        elif dot == '..':
            if out and (len(out) > 1 or out[0] != ''): out.pop()
            if i == len(segs) - 1: out.append('')
