UNICODE_CLASSES = {}

def unicode_class(which):
    if which in UNICODE_CLASSES: return UNICODE_CLASSES[which]
    if which == 'digit':
        vals = [i for i in range(0x110000) if unicodedata.category(chr(i)) == 'Nd']
    elif which == 'word':
