            data.append(chunk)
        except (ValueError, OSError, Failure):
            raise Failure('Failed to parse form data: ' + s)
    data.append(('--' + boundary + '--\r\n').encode())
    return b''.join(data), 'multipart/form-data; boundary=' + boundary


def check_header(value):
    if any(ord(ch) < 32 and ch != '\t' or ord(ch) == 127 for ch in value):
        raise Failure('failed to parse header value')
    return value


class ClientConfig:
    def __init__(self, c, generator):
        self.c, self.generator = c, generator
        self.body, self.lines = b'', None
        formtype = None
        if c.d is not None: self.body = c.d.encode('utf-8')
        elif c.D is not None: self.body = read_file(c.D)
        elif c.Z is not None:
            s = read_file(c.Z, True)
            self.lines = [line.encode() for line in s.splitlines()]
        elif c.form:
            self.body, formtype = parse_form(c.form)
            if not any(o.key == 'method' for o in c.seen): c.method = 'POST'
        h = collections.OrderedDict()
        h['accept'] = check_header(c.A) if c.A is not None else '*/*'
        if not c.disable_compression: h['accept-encoding'] = 'gzip, compress, deflate, br'
        h['user-agent'] = 'oha/1.12.1'
        if formtype: h['content-type'] = formtype
        if c.T is not None: h['content-type'] = check_header(c.T)
        if c.host is not None: h['host'] = check_header(c.host)
        if c.a is not None and c.aws is None:
            if ':' not in c.a: raise Failure('Parse auth')
            h['authorization'] = 'Basic ' + base64.b64encode(c.a.encode()).decode()
        if c.disable_keepalive and c.http != '2': h['connection'] = 'close'
        for k, v in c.H: h[k] = v
        self.headers = h
        self.dns_cache = {}
        self.dns_lock = threading.Lock()
        self.ssl_context = ssl.create_default_context()
        if c.insecure:
            self.ssl_context.check_hostname = False
            self.ssl_context.verify_mode = ssl.CERT_NONE
        if c.cacert is not None:
            ca = read_file(c.cacert)
            if b'-----BEGIN CERTIFICATE-----' in ca:
                try: self.ssl_context.load_verify_locations(cadata=ca.decode())
                except (ssl.SSLError, UnicodeError): raise Failure('invalid peer certificate: BadEncoding')
        if c.cert is not None:
            crt, key = read_file(c.cert), read_file(c.key)
            if b'PRIVATE KEY' not in key:
                raise Failure(f"\nthread 'main' ({os.getpid()}) panicked at src/tls_config.rs:39:76:\ncalled `Result::unwrap()` on an `Err` value: NoItemsFound\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n", 101)
            try: self.ssl_context.load_cert_chain(c.cert, c.key)
            except ssl.SSLError: raise Failure('invalid peer certificate: BadEncoding')
        self.ssl_context.set_alpn_protocols(['h2'] if c.http == '2' else ['http/1.1'])
        if generator.initial.hostname is None:
            raise Failure('failed to get host from URL')
        if not c.no_pre_lookup:
            if not (c.unix_socket and generator.initial.scheme != 'https'):
                targets = generator.urls if generator.urls else [generator.initial]
                for u in targets:
                    host, port = self.endpoint(u)
                    try: self.resolve(host, port)
                    except RequestError as e: raise Failure(str(e))
            if c.x is not None:
                if not c.x.hostname: raise Failure('failed to get host from URL')
                try: self.resolve(c.x.hostname, c.x.port_or_default)
                except RequestError as e: raise Failure(str(e))

    def endpoint(self, u):
        host, port = u.hostname, u.port_or_default
        opts = [(h2.strip('[]'), p2) for h, p, h2, p2 in self.c.connect_to if h == u.host and p == port]
        if opts: host, port = random.choice(opts)
        return host, port

    def resolve(self, host, port):
        key = (host, port)
        if not host: raise RequestError('failed to get host from URL')
        if not self.c.no_pre_lookup and key in self.dns_cache: return self.dns_cache[key]
        try:
            ip = ipaddress.ip_address(host)
            result = [(socket.AF_INET6 if ip.version == 6 else socket.AF_INET, str(ip), port)]
        except ValueError:
            if host.lower().rstrip('.') == 'localhost' or host.lower().endswith('.localhost'):
                if self.c.ipv6 and not self.c.ipv4: result = [(socket.AF_INET6, '::1', port)]
                else: result = [(socket.AF_INET, '127.0.0.1', port)]
            else:
                family = socket.AF_INET if self.c.ipv4 else socket.AF_INET6 if self.c.ipv6 else socket.AF_UNSPEC
                try:
                    results = socket.getaddrinfo(host, port, family, socket.SOCK_STREAM)
                    result = list(dict.fromkeys((fam, addr[0], addr[1]) for fam, _, _, _, addr in results))
                    if not result: raise OSError()
                except OSError:
                    raise RequestError('proto error: io error: Network is unreachable (os error 101)')
        if not self.c.no_pre_lookup: self.dns_cache[key] = result
        return result

    def make_request(self, u, body=None):
        if body is None:
            body = random.choice(self.lines) if self.lines else self.body
        h = self.headers.copy()
        proxy = self.c.x is not None and u.scheme != 'https'
        http = self.c.proxy_http if proxy else self.c.http
        if proxy:
            for k, v in self.c.proxy_header: h[k] = v
        if http != '2' and 'host' not in h: h['host'] = u.authority or ''
        uri = u.string.split('#')[0] if proxy or http == '2' else u.request_path
        if self.c.aws is not None:
            h = self.sign(u, body, h)
        return self.c.method, uri, http, h, body

    def sign(self, u, body, original):
        access, secret, region, service = self.c.aws
        now = datetime.datetime.now(datetime.timezone.utc)
        date = now.strftime('%Y%m%d')
        amzdate = now.strftime('%Y%m%dT%H%M%SZ')
        h = collections.OrderedDict([('host', u.hostname), ('x-amz-date', amzdate), ('content-length', str(len(body)))])
        if self.c.aws_session is not None: h['x-amz-security-token'] = self.c.aws_session
        for k, v in original.items():
            if k != 'host': h[k] = v
        signed = ['content-length', 'host', 'x-amz-date']
        if self.c.aws_session is not None: signed.append('x-amz-security-token')
        signed.sort()
        canonical = '\n'.join([self.c.method, u.path or '/', '&'.join(sorted((u.query or '').split('&'))), ''.join(k + ':' + h[k].strip() + '\n' for k in signed), ';'.join(signed), hashlib.sha256(body).hexdigest()])
        scope = date + '/' + region + '/' + service + '/aws4_request'
        string = 'AWS4-HMAC-SHA256\n' + amzdate + '\n' + scope + '\n' + hashlib.sha256(canonical.encode()).hexdigest()
        key = ('AWS4' + secret).encode()
        for part in [date, region, service, 'aws4_request']: key = hmac.new(key, part.encode(), hashlib.sha256).digest()
        sig = hmac.new(key, string.encode(), hashlib.sha256).hexdigest()
        h['authorization'] = f'AWS4-HMAC-SHA256 Credential={access}/{scope},SignedHeaders={";".join(signed)},Signature={sig}'
        return h


def dump_request(req):
    method, uri, http, headers, body = req
    v = '2.0' if http == '2' else http
    s = f'Request {{\n    method: {method},\n    uri: {uri},\n    version: HTTP/{v},\n    headers: {{\n'
    for k, val in headers.items(): s += f'        "{k}": {header_repr(val)},\n'
    s += '    },\n    body: Full {\n'
    if body: s += '        data: Some(\n            ' + rust_bytes(body) + ',\n        ),\n'
    else: s += '        data: None,\n'
    return s + '    },\n}\n'


def dump_response(response):
    status, version, headers, body = response
    s = f'Response {{\n    status: {status},\n    version: HTTP/{version},\n    headers: {{\n'
    for k, vals in headers.items():
        for value in vals: s += f'        "{k}": {header_repr(value)},\n'
    return s + '    },\n    body: ' + rust_bytes(body) + ',\n}\n'


class Connection:
    def __init__(self, client):
        self.client = client
        self.sock = None
        self.buffer = bytearray()
        self.endpoint_key = None
        self.deadline = None
        self.abort_time = None
        self.last_new = False
        self.dns = None
        self.dialup = None
        self.h2 = None

    def close(self):
        if self.sock:
            try: self.sock.close()
            except OSError: pass
        self.sock = None
        self.h2 = None
        self.buffer.clear()

    def timeout(self):
        now = time.perf_counter()
        times = [t for t in (self.deadline, self.abort_time) if t is not None]
        if times:
            left = min(times) - now
            if left <= 0: self.timed_out()
            return max(left, 0.000001)
        return None

    def timed_out(self):
        now = time.perf_counter()
        if self.abort_time is not None and now >= self.abort_time and (self.deadline is None or self.abort_time < self.deadline):
            raise RequestError('aborted due to deadline')
        raise RequestError('timeout')

    def map_error(self, e):
        if isinstance(e, RequestError): return e
        if isinstance(e, (socket.timeout, TimeoutError)):
            try: self.timed_out()
            except RequestError as x: return x
        if isinstance(e, ssl.SSLCertVerificationError):
            msg = str(e).lower()
            if 'self-signed' in msg or 'local issuer' in msg or 'issuer certificate' in msg: return RequestError('invalid peer certificate: UnknownIssuer')
            if 'expired' in msg: return RequestError('invalid peer certificate: Expired')
            if 'mismatch' in msg: return RequestError('invalid peer certificate: NotValidForName')
            return RequestError('invalid peer certificate: UnknownIssuer')
        if isinstance(e, ssl.SSLError): return RequestError('received corrupt message of type InvalidContentType')
        if isinstance(e, OSError): return RequestError(os_error(e))
        return RequestError(str(e))

    def connect(self, u, start):
        c = self.client.c
        target = c.x or u
        unix = c.unix_socket and u.scheme != 'https' and not c.x
        host, port = self.client.endpoint(target) if not c.x else (target.hostname, target.port_or_default)
        key = (host, port, u.scheme == 'https', bool(c.x), unix)
        self.dns = self.dialup = None
        self.last_new = False
        if self.sock is not None and self.endpoint_key == key:
            try:
                readable, _, _ = select.select([self.sock], [], [], 0)
                if readable and not isinstance(self.sock, ssl.SSLSocket) and not self.sock.recv(1, socket.MSG_PEEK): self.close()
            except OSError: self.close()
            if self.sock is not None: return
        self.close()
        self.endpoint_key = key
        self.last_new = True
        ct = c.connect_timeout
        ctleft = self.timeout()
        if ctleft is not None: ct = min(ct, ctleft)
        if unix:
            self.dns = time.perf_counter() - start
            sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
            sock.settimeout(max(ct, 0.000001))
            try: sock.connect(c.unix_socket)
            except Exception:
                sock.close(); raise
        else:
            addresses = self.client.resolve(host, port)
            self.dns = time.perf_counter() - start
            fam, addr, port = random.choice(addresses)
            sock = socket.socket(fam, socket.SOCK_STREAM)
            sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
