            except Exception:
                sock.close(); raise
        self.sock = sock
        try:
            if c.x and target.scheme == 'https':
                self.sock = self.client.ssl_context.wrap_socket(self.sock, server_hostname=target.hostname)
            if c.x and u.scheme == 'https':
                connheaders = collections.OrderedDict(c.proxy_header)
                authority = (u.host or '') + ':' + str(u.port_or_default)
                text = f'CONNECT {authority} HTTP/1.1\r\nhost: {authority}\r\n'
                for k, v in connheaders.items(): text += k + ': ' + v + '\r\n'
                self.sock.sendall((text + '\r\n').encode())
                block = self.read_until(b'\r\n\r\n')
                if not re.match(br'HTTP/1\.[01] 200', block): raise RequestError('unsuccessful tunnel')
            if u.scheme == 'https':
