            if len(self.buffer) > limit: raise RequestError('message head is too large')
            more = self.receive()
            if not more: raise RequestError('connection closed before message completed')
            self.buffer.extend(more)

    def read_exact(self, n):
        data = bytearray()
        if self.buffer:
            take = min(n, len(self.buffer)); data += self.buffer[:take]; del self.buffer[:take]
        while len(data) < n:
            more = self.receive(min(n - len(data), 65536))
            if not more: raise RequestError('error reading a body from connection')
            data += more
