            lines = block[:-4].split(b'\r\n')
            m = re.match(br'^HTTP/(1\.[01]) ([0-9]{3})(?: |$)', lines[0])
            if not m:
                if not lines[0].startswith((b'HTTP/1.0', b'HTTP/1.1')): raise RequestError('invalid HTTP version parsed')
                raise RequestError('invalid HTTP status-code parsed')
            version, status = m[1].decode(), int(m[2])
            headers = collections.OrderedDict()
            for line in lines[1:]:
                name, sep, val = line.partition(b':')
                try: name = name.decode('ascii').lower()
                except UnicodeError: raise RequestError('invalid HTTP header parsed')
                if not sep or not TOKEN_RE.fullmatch(name): raise RequestError('invalid HTTP header parsed')
                headers.setdefault(name, []).append(val.strip(b' \t'))
            if 100 <= status < 200 and status != 101: continue
            break
        def header(key): return b', '.join(headers.get(key, [])).decode('latin1')
        closes = header('connection').lower() == 'close' or req_http == '1.0' or version == '1.0' and 'keep-alive' not in header('connection').lower()
        if method == 'HEAD' or status < 200 or status in (204, 304):
            body = b''
        elif 'chunked' in header('transfer-encoding').lower():
            chunks = []
            try:
                while True:
                    line = self.read_until(b'\r\n', 1024)
                    n = int(line.split(b';', 1)[0].strip(), 16)
                    if n == 0:
                        while self.read_until(b'\r\n') != b'\r\n': pass
                        break
                    chunks.append(self.read_exact(n))
                    if self.read_exact(2) != b'\r\n': raise ValueError()
            except ValueError: raise RequestError('error reading a body from connection')
            body = b''.join(chunks)
        elif header('content-length'):
            try: length = int(header('content-length'))
            except ValueError: raise RequestError('invalid content-length parsed')
            if length < 0: raise RequestError('invalid content-length parsed')
            body = self.read_exact(length)
        else:
            body = bytes(self.buffer)
            self.buffer.clear()
            while True:
                more = self.receive()
                if not more: break
                body += more
            closes = True
        if closes: self.close()
        return status, version, headers, body

    def perform_once(self, u, req, start):
        self.connect(u, start)
        method, uri, http, headers, body = req
        if http == '2':
            from http2 import H2Connection
            if self.h2 is None: self.h2 = H2Connection(self)
            return self.h2.request(u, req)
        if http == '0.9': raise RequestError('operation was canceled')
        parts = [f'{method} {uri} HTTP/{http}\r\n'.encode()]
        for k, v in headers.items(): parts.append((k + ': ' + v + '\r\n').encode('utf-8'))
        sendbody = body
        if body and 'content-length' not in headers and 'transfer-encoding' not in headers:
            parts.append(f'content-length: {len(body)}\r\n'.encode())
        if 'chunked' in headers.get('transfer-encoding', ''):
            sendbody = (format(len(body), 'x').encode() + b'\r\n' + body + b'\r\n' if body else b'') + b'0\r\n\r\n'
        self.send(b''.join(parts) + b'\r\n' + sendbody)
        response = self.read_response(method, http)
        if self.client.c.disable_keepalive and http != '2': self.close()
        return response

    def request(self, u, req, start, debug=False):
        dns = dial = None
        try:
            limit = 0 if debug else self.client.c.redirect
            for count in range(limit + 1):
                response = self.perform_once(u, req, start)
                if dns is None: dns, dial = self.dns, self.dialup
                status, _, headers, body = response
                locations = headers.get('location')
                if debug or self.client.c.http == '2' or not (300 <= status < 400) or not locations or limit == 0:
                    return response, dns, dial, u, req
                if count == limit:
                    self.close()
                    raise RequestError('Redirection limit has reached')
                try: u = u.join(locations[0].decode('utf-8'))
                except (Failure, UnicodeError) as e: raise RequestError(str(e))
                req = self.client.make_request(u, req[-1])
        except Exception as e:
            err = self.map_error(e)
            self.close()
            raise err
