import collections
import json
import math
from decimal import Decimal

PERCENTILES = [10, 25, 50, 75, 90, 95, 99, 99.9, 99.99]


def number_string(v, display=False):
    if math.isnan(v): return 'NaN' if display else 'null'
    if math.isinf(v): return ('-inf' if v < 0 else 'inf') if display else 'null'
    s = repr(v)
    if 'e' in s:
        exponent = int(s.split('e')[1])
        if display or -5 <= exponent < 16:
            s = format(Decimal(s), 'f')
        else:
            a, b = s.split('e')
            s = a + 'e' + str(int(b))
    if display and s.endswith('.0'): s = s[:-2]
    return s


def json_format(value, level=0):
    # Keep map order and IEEE-754 special values compatible with the report.
    if isinstance(value, dict):
        if not value: return '{}'
        return '{\n' + ',\n'.join('  ' * (level+1) + json.dumps(str(k), ensure_ascii=False) + ': ' + json_format(v, level+1) for k, v in value.items()) + '\n' + '  ' * level + '}'
    if isinstance(value, list):
        return '[' + ', '.join(json_format(v, level+1) for v in value) + ']'
    if isinstance(value, float): return number_string(value)
    return json.dumps(value, ensure_ascii=False)


