def benchmark(c, client):
    begin = time.perf_counter()
    limit = begin + c.z + .0005 if c.z is not None else None
    interrupt = threading.Event()
    lock = threading.Lock()
    index = 0
    results, errors = [], collections.Counter()
    conns = []
    q = c.q if c.q is not None and c.q > 0 else 0
    if c.q is not None and math.isnan(c.q):
        raise Failure(f"\nthread 'main' ({os.getpid()}) panicked at /rustc/ded5c06cf21d2b93bffd5d884aa6e96934ee4234/library/core/src/time.rs:966:23:\ncannot convert float seconds to Duration: value is either too big or NaN\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n", 101)

    def worker():
        nonlocal index
        conn = Connection(client)
        with lock: conns.append(conn)
        while not interrupt.is_set():
            with lock:
                now = time.perf_counter()
                if limit is not None:
                    if now >= limit: break
                elif index >= c.n: break
                i = index
                index += 1
            target = begin
            if q and math.isfinite(q): target += i/q
            elif c.burst_delay is not None:
                if not c.burst_rate:
                    if limit is not None: interrupt.wait(max(0, limit-time.perf_counter()))
                    else: interrupt.wait()
                    break
                target += (i//c.burst_rate + 1) * c.burst_delay
            now = time.perf_counter()
            if limit is not None and target >= limit:
                interrupt.wait(max(0, limit-now))
                break
            if target > now:
                if interrupt.wait(target-now): break
            if limit is not None and time.perf_counter() >= limit: break
            start = time.perf_counter()
            conn.deadline = start + max(.001, c.t + .0005) if c.t is not None else None
            conn.abort_time = limit if limit is not None and not c.wait_ongoing_requests_after_deadline and c.http != '2' else None
            try:
                u = client.generator.get()
                req = client.make_request(u)
                response, dns, dial, final_url, final_req = conn.request(u, req, start)
                delay_end = time.perf_counter()
                status, _, _, body = response
                end = time.perf_counter()
                corrected = target if c.latency_correction and q else None
                duration_start = corrected if corrected is not None else start
                result = {
                    'url': final_req[1],
                    'start': round(start-begin, 9),
                    'correction': round(corrected-begin, 9) if corrected is not None else None,
                    'end': round(end-begin, 9),
                    'duration': round(end-duration_start, 9),
                    'delay': round(delay_end-start, 9),
                    'dns': round(dns, 9) if dns is not None else None,
                    'dial': round(dial, 9) if dial is not None else None,
                    'bytes': len(body),
                    'status': status,
                }
                with lock: results.append(result)
            except (RequestError, Failure) as e:
                with lock: errors[str(e)] += 1
            except Exception as e:
                with lock: errors[str(e)] += 1
        conn.close()

    def on_interrupt(signum, frame):
        interrupt.set()
        with lock:
            for conn in conns:
                conn.abort_time = time.perf_counter()
                if conn.sock:
