class H2Connection:
    def __init__(self, connection):
        self.conn = connection
        self.decoder = Decoder()
        self.next_stream = 1
        self.window = 65535
        self.initial_stream_window = 65535
        self.stream_window = 65535
        self.max_frame = 16384
        self.pending = []
        self.conn.send(b'PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n')
        # Disable server push; it is not a requested response in a load test.
        self.frame(4, 0, 0, struct.pack('!HI', 2, 0))

    def frame(self, kind, flags, stream, payload):
        self.conn.send(len(payload).to_bytes(3,'big')+bytes([kind,flags])+stream.to_bytes(4,'big')+payload)

    def read(self):
        try:
            head = self.conn.read_exact(9)
            length = int.from_bytes(head[:3], 'big')
            kind, flags, stream = head[3], head[4], int.from_bytes(head[5:], 'big') & 0x7fffffff
            if length > 16777215 or kind > 20: raise RequestError('http2 error')
            payload = self.conn.read_exact(length)
            return kind, flags, stream, payload
        except RequestError as e:
            if str(e) in ('timeout', 'aborted due to deadline'): raise
            raise RequestError('http2 error')

    def control(self, item, stream):
        kind, flags, sid, payload = item
        if kind == 4:
            if not flags & 1:
                for i in range(0,len(payload)-5,6):
                    n, val = struct.unpack('!HI', payload[i:i+6])
                    if n == 4:
                        self.stream_window += val-self.initial_stream_window
                        self.initial_stream_window = val
                    elif n == 5: self.max_frame = val
                self.frame(4,1,0,b'')
            return True
        if kind == 6:
            if not flags & 1: self.frame(6,1,0,payload)
            return True
        if kind == 8:
            if len(payload) != 4: raise RequestError('http2 error')
            amount = int.from_bytes(payload, 'big') & 0x7fffffff
            if sid == 0: self.window += amount
            elif sid == stream: self.stream_window += amount
            return True
        if kind == 7:
            raise RequestError('http2 error')
        if kind == 3 and sid == stream:
            raise RequestError('http2 error')
        return False

    def request(self, url, req):
        method, _, _, headers, body = req
        stream = self.next_stream; self.next_stream += 2
        self.stream_window = self.initial_stream_window
        fields = [(b':method', method.encode()), (b':scheme', url.scheme.encode()),
                  (b':authority', (url.authority or '').encode()), (b':path', url.request_path.encode())]
        for k,v in headers.items():
            if k not in ('connection', 'transfer-encoding', 'upgrade', 'keep-alive', 'proxy-connection'):
                fields.append((k.encode(),v.encode()))
        if body and 'content-length' not in headers:
            fields.append((b'content-length',str(len(body)).encode()))
        block = encode(fields)
        pos = 0
        while pos < len(block):
            chunk = block[pos:pos+self.max_frame]
            last = pos+len(chunk) == len(block)
            self.frame(1 if pos == 0 else 9, (4 if last else 0) | (1 if pos == 0 and not body else 0), stream, chunk)
            pos += len(chunk)
        pos = 0
        while pos < len(body):
            capacity = min(self.max_frame, self.window, self.stream_window)
            if capacity <= 0:
                item = self.read()
                if not self.control(item, stream): self.pending.append(item)
                continue
            chunk = body[pos:pos+capacity]
            pos += len(chunk)
            self.frame(0, 1 if pos == len(body) else 0, stream, chunk)
            self.window -= len(chunk); self.stream_window -= len(chunk)
        status = 0
        response_headers = collections.OrderedDict()
        data = bytearray()
        block = bytearray()
        headers_ended_stream = False
        try:
            while True:
                item = self.pending.pop(0) if self.pending else self.read()
                kind, flags, sid, payload = item
                if self.control(item, stream): continue
                if sid != stream: continue
                if kind in (1,9):
                    if kind == 1:
                        if flags & 8:
                            pad = payload[0]; payload = payload[1:len(payload)-pad] if pad else payload[1:]
                        if flags & 32: payload = payload[5:]
                        headers_ended_stream = bool(flags & 1)
                    block.extend(payload)
                    if flags & 4:
                        parsed = self.decoder.decode(bytes(block)); block.clear()
                        for n,v in parsed:
                            if n == b':status': status = int(v)
                            elif not n.startswith(b':'): response_headers.setdefault(n.decode('ascii').lower(),[]).append(v)
                        if 100 <= status < 200:
                            response_headers.clear(); status = 0
                        elif headers_ended_stream: break
                elif kind == 0:
                    frame_len = len(payload)
                    if flags & 8:
                        pad = payload[0]; payload = payload[1:len(payload)-pad] if pad else payload[1:]
                    if method != 'HEAD': data.extend(payload)
                    if frame_len:
                        self.frame(8,0,0,frame_len.to_bytes(4,'big'))
                        self.frame(8,0,stream,frame_len.to_bytes(4,'big'))
                    if flags & 1: break
        except (IndexError, ValueError, KeyError, UnicodeError):
            raise RequestError('http2 error')
        if not status: raise RequestError('http2 error')
        return status, '2.0', response_headers, bytes(data)
